<?php
namespace App\Http\Controllers;
use App\Http\Requests\StorePaperUploadRequest; use App\Models\Paper; use App\Services\FileCompressionService; use App\Services\PdfCompressionService; use App\Services\UploadMetadataService; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class PaperController extends Controller {
 public function index(Request $r){$q=Paper::where('status','approved')->latest();if($s=trim((string)$r->query('q')))$q->where(fn($x)=>$x->where('paper_name','like',"%$s%")->orWhere('subject_name','like',"%$s%")->orWhere('paper_code','like',"%$s%")->orWhere('subject_code','like',"%$s%"));return response()->json($q->limit(100)->get()->map(fn(Paper $p)=>['id'=>$p->id,'paper_code'=>$p->paper_code,'paper_name'=>$p->paper_name?:$p->original_name,'year'=>$p->year,'session'=>$p->session,'branch'=>$p->branch,'semester'=>$p->semester,'download_url'=>route('papers.download',$p)]));}
 public function store(StorePaperUploadRequest $r,UploadMetadataService $meta,FileCompressionService $images,PdfCompressionService $pdf){$data=$meta->enrichPaper($r->safe()->except('file'));$fingerprint=$meta->fingerprintPaper($data);if($fingerprint&&Paper::where('fingerprint',$fingerprint)->exists())return response()->json(['message'=>'This exact paper record already exists.'],422);$file=$r->file('file');$path=$file->store('papers','public');$abs=storage_path('app/public/'.$path);$mime=$file->getMimeType()?:'application/octet-stream';if($mime==='application/pdf')$pdf->compressInPlace($abs);elseif(str_starts_with($mime,'image/'))$images->compressImageInPlace($abs);$paper=Paper::create(array_merge($data,['user_id'=>$r->user()->id,'file_path'=>$path,'original_name'=>$file->getClientOriginalName(),'mime_type'=>$mime,'file_size'=>filesize($abs)?:$file->getSize(),'fingerprint'=>$fingerprint,'status'=>'pending']));return response()->json(['message'=>'Paper uploaded and sent for Admin review.','id'=>$paper->id],201);}
 public function download(Paper $paper){abort_unless($paper->status==='approved',404);abort_unless(Storage::disk('public')->exists($paper->file_path),404);return Storage::disk('public')->download($paper->file_path,$paper->original_name);}
}
